func (l *Limiter) Allow(ctx context.Context, key string) (bool, error) {
	b := l.local(key)
	if b.take() {
		return true, nil
	}

	granted, err := l.store.Lease(ctx, key, l.blockSize)
	if err != nil {
		// The store is unreachable. Serve from whatever the local budget last knew
		// and mark the decision degraded. Denying everything here is what the old
		// exact limiter did, and it turned a dependency blip into an outage.
		l.degraded.Add(ctx, 1)
		return b.takeReserve(), nil
	}

	b.refill(granted)
	return b.take(), nil
}

// The reconciler compares what the fleet actually allowed against what an exact
// counter would have allowed over the same window. An approximate limiter that does
// not publish its own error cannot be told apart from a broken exact one.
func (r *Reconciler) report(ctx context.Context, w Window) {
	allowed := r.fleetAllowed(w)
	exact := r.storeAllowed(w)
	if exact == 0 {
		return
	}

	drift := float64(allowed-exact) / float64(exact)
	r.driftGauge.Record(ctx, drift, metric.WithAttributes(w.Attributes()...))
}
